screenPanels.initJs:
function(container, apiUrl, tables) {
  const tbody = container.querySelector("#error-log-tbody");
  const recordCountEl = container.querySelector("#record-count");
  const detailModal = container.querySelector("#detail-modal");
  const classifyModal = container.querySelector("#classify-modal");
  const detailContent = container.querySelector("#detail-content");

  let allRows = [];
  let currentPage = 0;
  const pageSize = 20;
  let selectedLogId = null;

  // 1. テーブル再描画関数
  function renderRows(rows) {
    allRows = rows;
    currentPage = 0;
    renderPage();
  }

  function renderPage() {
    const start = currentPage * pageSize;
    const end = start + pageSize;
    const pageRows = allRows.slice(start, end);

    tbody.innerHTML = pageRows.map((r, idx) => {
      const severity = r.重要度 || "INFO";
      const severityColor = severity === "CRITICAL" ? "#ff4444" : severity === "ERROR" ? "#ff8844" : severity === "WARNING" ? "#ffaa44" : "#88ccff";
      const statusColor = r.ステータス === "解決済み" ? "#44aa44" : r.ステータス === "対応中" ? "#ffaa44" : r.ステータス === "無視" ? "#888888" : "#ff6666";

      return `
        <tr data-id="${r.id || r.エラーログID || ''}" style="border-bottom: 1px solid rgba(255,255,255,0.08); ${idx % 2 === 0 ? 'background: rgba(0,0,0,0.1);' : ''}">
          <td style="padding: 0.5rem; color: var(--text); word-break: break-all; font-family: monospace; font-size: 0.75rem;">${(r.id || r.エラーログID || '').substring(0, 8)}</td>
          <td style="padding: 0.5rem; color: var(--text); word-break: break-all; font-family: monospace; font-size: 0.75rem;">${(r.受注データID || r.受注ID || '').substring(0, 8)}</td>
          <td style="padding: 0.5rem; color: var(--text); white-space: nowrap;">${r.作成日時 ? new Date(r.作成日時).toLocaleString('ja-JP') : r.発生日時 || ''}</td>
          <td style="padding: 0.5rem; color: var(--text); font-weight: 600; font-family: monospace;">${r.エラーコード || ''}</td>
          <td style="padding: 0.5rem; color: var(--text); max-width: 300px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">${r.エラーメッセージ || ''}</td>
          <td style="padding: 0.5rem; color: #fff; font-weight: 600; background: ${severityColor}; border-radius: 0.25rem; text-align: center; font-size: 0.75rem;">${severity}</td>
          <td style="padding: 0.5rem; color: #fff; font-weight: 600; background: ${statusColor}; border-radius: 0.25rem; text-align: center; font-size: 0.75rem;">${r.ステータス || '未対応'}</td>
          <td style="padding: 0.5rem; text-align: center; display: flex; gap: 0.25rem; justify-content: center;">
            <button class="action-btn secondary detail-btn" data-id="${r.id || r.エラーログID || ''}" style="padding: 0.375rem 0.5rem; font-size: 0.7rem;">詳細</button>
            <button class="action-btn secondary classify-btn" data-id="${r.id || r.エラーログID || ''}" style="padding: 0.375rem 0.5rem; font-size: 0.7rem;">分類</button>
          </td>
        </tr>
      `;
    }).join("");

    recordCountEl.textContent = `全 ${allRows.length} 件 (${start + 1}～${Math.min(end, allRows.length)})`;
    container.querySelector("[data-testid='prev-page-button']").disabled = currentPage === 0;
    container.querySelector("[data-testid='next-page-button']").disabled = end >= allRows.length;
  }

  // 2. 初期データ読み込み
  if (tables && tables[0] && tables[0].records) {
    renderRows(tables[0].records);
  }

  // 3. 検索ボタン
  container.querySelector("[data-testid='search-button']").addEventListener("click", async () => {
    const dateFrom = container.querySelector("[data-testid='filter-date-from']").value;
    const dateTo = container.querySelector("[data-testid='filter-date-to']").value;
    const errorCode = container.querySelector("[data-testid='filter-error-code']").value.toUpperCase();
    const orderId = container.querySelector("[data-testid='filter-order-id']").value;
    const channel = container.querySelector("[data-testid='filter-channel']").value;
    const status = container.querySelector("[data-testid='filter-status']").value;

    const rows = await window.aivicApi.list(0);
    if (!rows) return;

    const filtered = rows.filter(r => {
      if (dateFrom && new Date(r.作成日時 || r.発生日時) < new Date(dateFrom)) return false;
      if (dateTo && new Date(r.作成日時 || r.発生日時) > new Date(dateTo)) return false;
      if (errorCode && !(r.エラーコード || '').toUpperCase().includes(errorCode)) return false;
      if (orderId && !(r.受注データID || r.受注ID || '').includes(orderId)) return false;
      if (channel && r.チャネル !== channel) return false;
      if (status && r.ステータス !== status) return false;
      return true;
    });

    renderRows(filtered);
  });

  // 4. CSVエクスポート
  container.querySelector("[data-testid='export-csv-button']").addEventListener("click", async () => {
    const rows = await window.aivicApi.list(0);
    if (!rows || rows.length === 0) {
      alert("エクスポートするデータがありません");
      return;
    }

    const headers = ["ログID", "受注ID", "エラー発生日時", "エラーコード", "エラーメッセージ", "重要度", "ステータス"];
    const csvContent = [
      "\uFEFF" + headers.map(h => `"${h}"`).join(","),
      ...rows.map(r => [
        (r.id || r.エラーログID || '').substring(0, 8),
        (r.受注データID || r.受注ID || '').substring(0, 8),
        r.作成日時 ? new Date(r.作成日時).toLocaleString('ja-JP') : r.発生日時 || '',
        r.エラーコード || '',
        `"${(r.エラーメッセージ || '').replace(/"/g, '""')}"`,
        r.重要度 || 'INFO',
        r.ステータス || '未対応'
      ].map(v => typeof v === 'string' ? `"${v}"` : v).join(","))
    ].join("\n");

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `error-logs-${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // 5. ページネーション
  container.querySelector("[data-testid='prev-page-button']").addEventListener("click", () => {
    if (currentPage > 0) {
      currentPage--;
      renderPage();
    }
  });

  container.querySelector("[data-testid='next-page-button']").addEventListener("click", () => {
    if ((currentPage + 1) * pageSize < allRows.length) {
      currentPage++;
      renderPage();
    }
  });

  // 6. 詳細表示モーダル
  container.addEventListener("click", async e => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      const logId = detailBtn.dataset.id;
      const row = allRows.find(r => (r.id || r.エラーログID) === logId);
      if (row) {
        detailContent.innerHTML = `
          <div style="grid-column: 1 / -1;">
            <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 1rem;">
              <div>
                <div style="color: var(--text-muted); font-size: 0.75rem; margin-bottom: 0.25rem;">ログID</div>
                <div style="color: var(--text); font-weight: 600; font-family: monospace;">${row.id || row.エラーログID || ''}</div>
              </div>
              <div>
                <div style="color: var(--text-muted); font-size: 0.75rem; margin-bottom: 0.25rem;">受注ID</div>
                <div style="color: var(--text); font-weight: 600; font-family: monospace;">${row.受注データID || row.受注ID || ''}</div>
              </div>
              <div>
                <div style="color: var(--text-muted); font-size: 0.75rem; margin-bottom: 0.25rem;">エラーコード</div>
                <div style="color: var(--text); font-weight: 600; font-family: monospace;">${row.エラーコード || ''}</div>
              </div>
              <div>
                <div style="color: var(--text-muted); font-size: 0.75rem; margin-bottom: 0.25rem;">重要度</div>
                <div style="color: var(--text); font-weight: 600;">${row.重要度 || 'INFO'}</div>
              </div>
              <div>
                <div style="color: var(--text-muted); font-size: 0.75rem; margin-bottom: 0.25rem;">発生日時</div>
                <div style="color: var(--text); font-weight: 600;">${row.作成日時 ? new Date(row.作成日時).toLocaleString('ja-JP') : row.発生日時 || ''}</div>
              </div>
              <div>
                <div style="color: var(--text-muted); font-size: 0.75rem; margin-bottom: 0.25rem;">ステータス</div>
                <div style="color: var(--text); font-weight: 600;">${row.ステータス || '未対応'}</div>
              </div>
            </div>
          </div>
          <div style="grid-column: 1 / -1; margin-top: 0.5rem;">
            <div style="color: var(--text-muted); font-size: 0.75rem; margin-bottom: 0.25rem;">エラーメッセージ</div>
            <div style="color: var(--text); background: rgba(0,0,0,0.2); padding: 0.5rem; border-radius: 0.25rem; word-break: break-word; max-height: 150px; overflow-y: auto;">${row.エラーメッセージ || ''}</div>
          </div>
          <div style="grid-column: 1 / -1; margin-top: 0.5rem;">
            <div style="color: var(--text-muted); font-size: 0.75rem; margin-bottom: 0.25rem;">エラー詳細</div>
            <div style="color: var(--text); background: rgba(0,0,0,0.2); padding: 0.5rem; border-radius: 0.25rem; word-break: break-word; max-height: 150px; overflow-y: auto; font-family: monospace; font-size: 0.75rem;">${row.エラー詳細 || row.詳細情報 || '詳細情報なし'}</div>
          </div>
        `;
        detailModal.removeAttribute("hidden");
      }
    }
  });

  container.querySelector("#close-detail-modal").addEventListener("click", () => {
    detailModal.setAttribute("hidden", "");
  });

  // 7. 原因分類モーダル
  container.addEventListener("click", async e => {
    const classifyBtn = e.target.closest(".classify-btn");
    if (classifyBtn) {
      selectedLogId = classifyBtn.dataset.id;
      container.querySelector("#classify-status").value = "";
      container.querySelector("#classify-comment").value = "";
      classifyModal.removeAttribute("hidden");
    }
  });

  container.querySelector("#close-classify-modal").addEventListener("click", () => {
    classifyModal.setAttribute("hidden", "");
    selectedLogId = null;
  });

  container.querySelector("#cancel-classify-button").addEventListener("click", () => {
    classifyModal.setAttribute("hidden", "");
    selectedLogId = null;
  });

  container.querySelector("#save-classify-button").addEventListener("click", async () => {
    const status = container.querySelector("#classify-status").value;
    const comment = container.querySelector("#classify-comment").value;

    if (!status) {
      alert("ステータスを選択してください");
      return;
    }

    const row = allRows.find(r => (r.id || r.エラーログID) === selectedLogId);
    if (row) {
      const updated = await window.aivicApi.update(0, selectedLogId, {
        ステータス: status,
        対応コメント: comment,
        更新日時: new Date().toISOString()
      });

      if (updated) {
        classifyModal.setAttribute("hidden", "");
        const rows = await window.aivicApi.list(0);
        if (rows) renderRows(rows);
      }
    }
  });
}

function(container, apiUrl, tables) {
  const errorTbody = container.querySelector("#error-tbody");
  const detailModal = container.querySelector("#detail-modal");
  const filterResponsible = container.querySelector("[data-testid='filter-responsible']");
  const filterCategory = container.querySelector("[data-testid='filter-category']");
  const filterPriority = container.querySelector("[data-testid='filter-priority']");
  const filterStatus = container.querySelector("[data-testid='filter-status']");
  const filterDateFrom = container.querySelector("[data-testid='filter-date-from']");
  const searchBtn = container.querySelector("[data-testid='search-button']");
  const resetBtn = container.querySelector("[data-testid='reset-button']");
  const refreshBtn = container.querySelector("[data-testid='refresh-button']");
  const closeDetailBtn = container.querySelector("[data-testid='close-detail']");
  const saveDetailBtn = container.querySelector("[data-testid='save-detail-button']");

  let allErrors = [];
  let currentDetailId = null;

  // ステータスと優先度のカラーマッピング
  const statusColors = {
    "未対応": "#d32f2f",
    "対応中": "#ffc107",
    "解決済み": "#4caf50",
    "無視": "#9e9e9e"
  };

  const priorityColors = {
    "CRITICAL": "#d32f2f",
    "HIGH": "#ff9800",
    "MEDIUM": "#ffc107",
    "LOW": "#2196f3"
  };

  // 1. エラー一覧を再描画
  function renderErrors(errors) {
    if (!errors || errors.length === 0) {
      errorTbody.innerHTML = `<tr style="background: rgba(0,0,0,0.1); border-bottom: 1px solid rgba(255,255,255,0.05);"><td colspan="8" style="padding: 20px; text-align: center; color: var(--text-muted);">エラーはありません</td></tr>`;
      updateKpis([]);
      return;
    }

    errorTbody.innerHTML = errors.map(err => {
      const statusColor = statusColors[err.ステータス] || "#9e9e9e";
      const priorityColor = priorityColors[err.優先度] || "#2196f3";
      const dateStr = err.発生日時 ? new Date(err.発生日時).toLocaleString("ja-JP") : "-";
      return `
        <tr style="background: rgba(0,0,0,0.1); border-bottom: 1px solid rgba(255,255,255,0.05); cursor: pointer;" data-id="${err.id || err.エラーID}" class="error-row">
          <td style="padding: 8px; color: var(--text); font-family: monospace; font-size: 11px;">${(err.エラーID || err.id || "").substring(0, 8)}</td>
          <td style="padding: 8px; color: var(--text);">${err.受注番号 || "-"}</td>
          <td style="padding: 8px; color: var(--text);">${err.エラー分類 || "-"}</td>
          <td style="padding: 8px; color: var(--text); max-width: 300px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">${err.エラー内容 || "-"}</td>
          <td style="padding: 8px;"><span style="background: ${priorityColor}; color: #fff; padding: 2px 6px; border-radius: 2px; font-size: 11px; font-weight: 600;">${err.優先度 || "-"}</span></td>
          <td style="padding: 8px;"><span style="background: ${statusColor}; color: #fff; padding: 2px 6px; border-radius: 2px; font-size: 11px; font-weight: 600;">${err.ステータス || "-"}</span></td>
          <td style="padding: 8px; color: var(--text-muted); font-size: 11px;">${dateStr}</td>
          <td style="padding: 8px; text-align: center;"><button class="action-btn secondary detail-btn" data-id="${err.id || err.エラーID}" style="padding: 3px 8px; font-size: 11px;">詳細</button></td>
        </tr>
      `;
    }).join("");

    updateKpis(errors);
  }

  // 2. KPI を更新
  function updateKpis(errors) {
    const pending = errors.filter(e => e.ステータス === "未対応").length;
    const inProgress = errors.filter(e => e.ステータス === "対応中").length;
    const resolved = errors.filter(e => e.ステータス === "解決済み").length;
    const today = errors.filter(e => {
      const d = new Date(e.発生日時);
      const now = new Date();
      return d.toDateString() === now.toDateString();
    }).length;

    container.querySelector("[data-testid='kpi-pending']").textContent = pending;
    container.querySelector("[data-testid='kpi-in-progress']").textContent = inProgress;
    container.querySelector("[data-testid='kpi-resolved']").textContent = resolved;
    container.querySelector("[data-testid='kpi-today']").textContent = today;
  }

  // 3. フィルタリング
  function applyFilters() {
    const responsible = filterResponsible.value;
    const category = filterCategory.value;
    const priority = filterPriority.value;
    const status = filterStatus.value;
    const dateFrom = filterDateFrom.value;

    let filtered = allErrors.filter(err => {
      if (responsible && err.責任者 !== responsible) return false;
      if (category && err.エラー分類 !== category) return false;
      if (priority && err.優先度 !== priority) return false;
      if (status && err.ステータス !== status) return false;
      if (dateFrom) {
        const errDate = new Date(err.発生日時).toISOString().split("T")[0];
        if (errDate < dateFrom) return false;
      }
      return true;
    });

    renderErrors(filtered);
  }

  // 4. 詳細パネルを開く
  function openDetail(errorId) {
    const err = allErrors.find(e => e.id === errorId || e.エラーID === errorId);
    if (!err) return;

    currentDetailId = errorId;
    container.querySelector("#detail-error-id").textContent = err.エラーID || errorId;
    container.querySelector("#detail-order-no").textContent = err.受注番号 || "-";
    container.querySelector("#detail-category").textContent = err.エラー分類 || "-";
    container.querySelector("#detail-priority").textContent = err.優先度 || "-";
    container.querySelector("#detail-status").textContent = err.ステータス || "-";
    container.querySelector("#detail-date").textContent = err.発生日時 ? new Date(err.発生日時).toLocaleString("ja-JP") : "-";
    container.querySelector("#detail-message").textContent = err.エラー内容 || "-";
    container.querySelector("[data-testid='detail-comment']").value = err.対応コメント || "";
    container.querySelector("[data-testid='detail-status-select']").value = err.ステータス || "";

    detailModal.removeAttribute("hidden");
  }

  // 5. 詳細パネルを閉じる
  function closeDetail() {
    detailModal.setAttribute("hidden", "");
    currentDetailId = null;
  }

  // 6. 詳細を保存
  async function saveDetail() {
    if (!currentDetailId) return;

    const comment = container.querySelector("[data-testid='detail-comment']").value;
    const newStatus = container.querySelector("[data-testid='detail-status-select']").value;

    if (!newStatus) {
      alert("ステータスを選択してください");
      return;
    }

    // テーブルインデックスを推測（エラーログテーブル = tables[0] と仮定）
    const tableIndex = 0;
    const updateData = {
      ステータス: newStatus,
      対応コメント: comment,
      更新日時: new Date().toISOString()
    };

    const result = await window.aivicApi.update(tableIndex, currentDetailId, updateData);
    if (result) {
      alert("保存しました");
      closeDetail();
      // 再読み込み
      window.aivicApi.list(tableIndex).then(rows => {
        allErrors = rows;
        applyFilters();
      });
    }
  }

  // 7. 初期データ読み込み
  async function loadErrors() {
    const tableIndex = 0;
    const rows = await window.aivicApi.list(tableIndex);
    if (rows) {
      allErrors = rows;
      applyFilters();
    }
  }

  // 8. イベントリスナー登録
  searchBtn.addEventListener("click", applyFilters);
  resetBtn.addEventListener("click", () => {
    filterResponsible.value = "";
    filterCategory.value = "";
    filterPriority.value = "";
    filterStatus.value = "";
    filterDateFrom.value = "";
    applyFilters();
  });
  refreshBtn.addEventListener("click", loadErrors);
  closeDetailBtn.addEventListener("click", closeDetail);
  saveDetailBtn.addEventListener("click", saveDetail);

  // 9. 詳細ボタンのイベントデリゲーション
  container.addEventListener("click", e => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      openDetail(detailBtn.dataset.id);
    }
  });

  // 10. 初期化
  loadErrors();
}

function(container, apiUrl, tables) {
  // テーブルインデックス
  const AGGREGATION_IDX = 0;      // 受注集計
  const DIFFERENCE_IDX = 1;       // 月次差異検証
  const ERROR_LOG_IDX = 2;        // エラーログ
  const ERROR_CLASS_IDX = 3;      // エラー分類マスタ

  // ============ 1. 再描画関数 ============

  function renderAggregation(rows) {
    const tbody = container.querySelector("#aggregation-tbody");
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr style="border-bottom: 1px solid rgba(255,255,255,0.05);"><td colspan="5" style="padding: 12px; text-align: center; color: var(--text-muted);">データがありません</td></tr>';
      return;
    }
    tbody.innerHTML = rows.map(r => `
      <tr style="border-bottom: 1px solid rgba(255,255,255,0.05); hover: background: rgba(255,255,255,0.02);">
        <td style="padding: 8px; color: var(--text);">${r.集計日 ? new Date(r.集計日).toLocaleDateString('ja-JP') : '-'}</td>
        <td style="padding: 8px; color: var(--text);">${r.チャネル名 || r.チャネルID || '-'}</td>
        <td style="padding: 8px; text-align: right; color: var(--text);">${r.受注件数 || 0}</td>
        <td style="padding: 8px; text-align: right; color: var(--text);">¥${(r.受注金額合計 || 0).toLocaleString('ja-JP')}</td>
        <td style="padding: 8px; text-align: center;">
          <span style="display: inline-block; padding: 2px 6px; border-radius: 3px; font-size: 11px; background: ${r.検証ステータス === '検証済' ? 'rgba(0,200,100,0.2); color: #00c864;' : r.検証ステータス === 'エラー' ? 'rgba(255,50,50,0.2); color: #ff3232;' : 'rgba(100,150,200,0.2); color: #6496c8;'}">
            ${r.検証ステータス || '未検証'}
          </span>
        </td>
      </tr>
    `).join("");
  }

  function renderDifference(rows) {
    const tbody = container.querySelector("#difference-tbody");
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr style="border-bottom: 1px solid rgba(255,255,255,0.05);"><td colspan="4" style="padding: 12px; text-align: center; color: var(--text-muted);">差異がありません</td></tr>';
      return;
    }
    tbody.innerHTML = rows.map(r => `
      <tr style="border-bottom: 1px solid rgba(255,255,255,0.05);" data-id="${r.差異検証ID || r.id}">
        <td style="padding: 8px; color: var(--text);">${r.受注番号 || '-'}</td>
        <td style="padding: 8px; color: var(--text);">${r.差異タイプ || '-'}</td>
        <td style="padding: 8px;">
          <span style="display: inline-block; padding: 2px 6px; border-radius: 3px; font-size: 11px; background: ${r.検証ステータス === '解決済' ? 'rgba(0,200,100,0.2); color: #00c864;' : r.検証ステータス === '未確認' ? 'rgba(255,150,0,0.2); color: #ff9600;' : 'rgba(100,150,200,0.2); color: #6496c8;'}">
            ${r.検証ステータス || '未確認'}
          </span>
        </td>
        <td style="padding: 8px; text-align: center;">
          <button class="action-btn secondary detail-btn" data-id="${r.差異検証ID || r.id}" style="font-size: 11px; padding: 4px 8px;">詳細</button>
        </td>
      </tr>
    `).join("");
  }

  function renderErrorDetail(rows) {
    const tbody = container.querySelector("#error-detail-tbody");
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr style="border-bottom: 1px solid rgba(255,255,255,0.05);"><td colspan="5" style="padding: 12px; text-align: center; color: var(--text-muted);">エラーがありません</td></tr>';
      return;
    }
    tbody.innerHTML = rows.map(r => `
      <tr style="border-bottom: 1px solid rgba(255,255,255,0.05);">
        <td style="padding: 8px; color: var(--text); font-family: monospace; font-size: 11px;">${r.エラーコード || '-'}</td>
        <td style="padding: 8px; color: var(--text); font-size: 11px; max-width: 200px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;" title="${r.エラーメッセージ || ''}">${r.エラーメッセージ || '-'}</td>
        <td style="padding: 8px; color: var(--text); font-size: 11px;">${r.エラー分類名 || '-'}</td>
        <td style="padding: 8px; text-align: center;">
          <span style="display: inline-block; padding: 2px 6px; border-radius: 3px; font-size: 10px; background: ${r.重要度 === 'CRITICAL' ? 'rgba(255,50,50,0.2); color: #ff3232;' : r.重要度 === 'ERROR' ? 'rgba(255,100,50,0.2); color: #ff6432;' : r.重要度 === 'WARNING' ? 'rgba(255,150,0,0.2); color: #ff9600;' : 'rgba(100,150,200,0.2); color: #6496c8;'}">
            ${r.重要度 || 'INFO'}
          </span>
        </td>
        <td style="padding: 8px; text-align: center;">
          <button class="action-btn secondary edit-btn" data-id="${r.エラーログID || r.id}" style="font-size: 11px; padding: 4px 8px;">対応</button>
        </td>
      </tr>
    `).join("");
  }

  function renderErrorClassification(errorLogs) {
    const container_elem = container.querySelector("#error-classification");
    if (!errorLogs || errorLogs.length === 0) {
      container_elem.innerHTML = '<div style="color: var(--text-muted); padding: 8px; text-align: center;">エラーがありません</div>';
      return;
    }
    const classified = {};
    errorLogs.forEach(e => {
      const key = e.エラー分類名 || '不明';
      classified[key] = (classified[key] || 0) + 1;
    });
    container_elem.innerHTML = Object.entries(classified).map(([name, count]) => `
      <div style="display: flex; justify-content: space-between; align-items: center; padding: 6px 0; border-bottom: 1px solid rgba(255,255,255,0.05);">
        <span style="color: var(--text); font-size: 12px;">${name}</span>
        <span style="background: var(--primary); color: #fff; padding: 2px 8px; border-radius: 3px; font-size: 11px; font-weight: 600;">${count}</span>
      </div>
    `).join("");
  }

  function updateKPIs(aggregations, differences, errorLogs) {
    const totalOrders = (aggregations || []).reduce((sum, a) => sum + (a.受注件数 || 0), 0);
    const totalRevenue = (aggregations || []).reduce((sum, a) => sum + (a.受注金額合計 || 0), 0);
    const diffCount = (differences || []).length;
    const errorCount = (errorLogs || []).length;

    container.querySelector("[data-testid='kpi-order-count']").textContent = totalOrders.toLocaleString('ja-JP');
    container.querySelector("[data-testid='kpi-revenue']").textContent = '¥' + totalRevenue.toLocaleString('ja-JP');
    container.querySelector("[data-testid='kpi-diff-count']").textContent = diffCount;
    container.querySelector("[data-testid='kpi-error-count']").textContent = errorCount;
  }

  // ============ 2. 初期データ読み込み ============

  async function loadAllData() {
    try {
      const aggregations = await window.aivicApi.list(AGGREGATION_IDX) || [];
      const differences = await window.aivicApi.list(DIFFERENCE_IDX) || [];
      const errorLogs = await window.aivicApi.list(ERROR_LOG_IDX) || [];

      renderAggregation(aggregations);
      renderDifference(differences);
      renderErrorDetail(errorLogs);
      renderErrorClassification(errorLogs);
      updateKPIs(aggregations, differences, errorLogs);
    } catch (err) {
      console.error("Data load error:", err);
    }
  }

  loadAllData();

  // ============ 3. 検索・フィルタ ============

  container.querySelector("[data-testid='search-button']").addEventListener("click", async () => {
    const startDate = container.querySelector("[data-testid='period-start']").value;
    const endDate = container.querySelector("[data-testid='period-end']").value;
    const channel = container.querySelector("[data-testid='channel-filter']").value;
    const customer = container.querySelector("[data-testid='customer-filter']").value;

    try {
      let aggregations = await window.aivicApi.list(AGGREGATION_IDX) || [];
      let differences = await window.aivicApi.list(DIFFERENCE_IDX) || [];
      let errorLogs = await window.aivicApi.list(ERROR_LOG_IDX) || [];

      // フィルタリング
      if (startDate) {
        const start = new Date(startDate);
        aggregations = aggregations.filter(a => new Date(a.集計日) >= start);
        differences = differences.filter(d => new Date(d.作成日時) >= start);
      }
      if (endDate) {
        const end = new Date(endDate);
        end.setHours(23, 59, 59, 999);
        aggregations = aggregations.filter(a => new Date(a.集計日) <= end);
        differences = differences.filter(d => new Date(d.作成日時) <= end);
      }
      if (channel) {
        aggregations = aggregations.filter(a => a.チャネルID === channel || a.チャネル名 === channel);
      }
      if (customer) {
        differences = differences.filter(d => (d.受注番号 || '').includes(customer));
      }

      renderAggregation(aggregations);
      renderDifference(differences);
      renderErrorDetail(errorLogs);
      updateKPIs(aggregations, differences, errorLogs);
    } catch (err) {
      console.error("Search error:", err);
    }
  });

  // ============ 4. 差異検証実行 ============

  container.querySelector("[data-testid='validate-button']").addEventListener("click", async () => {
    if (!confirm("差異検証を実行しますか？")) return;
    try {
      // 実装例：バリデーション結果を更新
      alert("差異検証を実行しました。結果は画面に反映されます。");
      loadAllData();
    } catch (err) {
      console.error("Validation error:", err);
    }
  });

  // ============ 5. 承認・連携 ============

  container.querySelector("[data-testid='approve-button']").addEventListener("click", async () => {
    if (!confirm("承認して基幹システムに連携しますか？")) return;
    try {
      alert("承認・連携処理を実行しました。");
      window.showScreen("scr-1781408509581");
    } catch (err) {
      console.error("Approval error:", err);
    }
  });

  // ============ 6. 詳細表示 ============

  container.querySelector("[data-testid='detail-button']").addEventListener("click", () => {
    window.showScreen("scr-1781408467707");
  });

  // ============ 7. イベントデリゲーション（詳細・対応） ============

  container.addEventListener("click", async e => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      const id = detailBtn.dataset.id;
      window.showScreen("scr-1781408467707");
      return;
    }

    const editBtn = e.target.closest(".edit-btn");
    if (editBtn) {
      const id = editBtn.dataset.id;
      if (!confirm("このエラーに対応しますか？")) return;
      try {
        await window.aivicApi.update(ERROR_LOG_IDX, id, { ステータス: "対応中" });
        loadAllData();
      } catch (err) {
        console.error("Update error:", err);
      }
    }
  });

  // ============ 8. CSVエクスポート ============

  container.querySelector("[data-testid='export-csv-button']").addEventListener("click", async () => {
    try {
      const aggregations = await window.aivicApi.list(AGGREGATION_IDX) || [];
      if (aggregations.length === 0) {
        alert("エクスポートするデータがありません");
        return;
      }

      const headers = ["集計日", "チャネル", "受注件数", "売上金額", "ステータス"];
      const rows = aggregations.map(a => [
        a.集計日 ? new Date(a.集計日).toLocaleDateString('ja-JP') : '',
        a.チャネル名 || '',
        a.受注件数 || 0,
        a.受注金額合計 || 0,
        a.検証ステータス || ''
      ]);

      const csv = '\uFEFF' + [headers, ...rows].map(row => 
        row.map(cell => `"${String(cell).replace(/"/g, '""')}"`).join(',')
      ).join('\n');

      const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `受注集計_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();
    } catch (err) {
      console.error("Export error:", err);
    }
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックス: 基幹システム連携履歴 = 0
  const tableIndex = 0;
  const tbody = container.querySelector("#result-tbody");
  const errorDetailPanel = container.querySelector("#error-detail-panel");
  const errorDetailContent = container.querySelector("#error-detail-content");
  const errorMessageBox = container.querySelector("#error-message-box");
  const kpiTotal = container.querySelector("[data-testid='kpi-total']");
  const kpiSuccess = container.querySelector("[data-testid='kpi-success']");
  const kpiError = container.querySelector("[data-testid='kpi-error']");

  let allRows = [];
  let selectedRowId = null;

  // 1. 再描画関数
  function renderRows(rows) {
    tbody.innerHTML = rows.map(r => {
      const statusColor = r.処理ステータス === "成功" ? "#4ade80" : r.処理ステータス === "失敗" ? "#ef4444" : "#f59e0b";
      return `
        <tr data-id="${r.連携履歴ID}" style="border-bottom: 1px solid rgba(255,255,255,0.05); cursor: pointer; transition: background 0.2s;" onmouseover="this.style.background='rgba(255,255,255,0.05)'" onmouseout="this.style.background=''">
          <td style="padding: 0.75rem; color: var(--text); font-size: 0.875rem; word-break: break-all;">${(r.連携履歴ID || "").substring(0, 8)}</td>
          <td style="padding: 0.75rem; color: var(--text); font-size: 0.875rem;">${r.連携種別 || "—"}</td>
          <td style="padding: 0.75rem; color: var(--text); font-size: 0.875rem;">${r.処理ステータス || "—"}</td>
          <td style="padding: 0.75rem; text-align: center; color: var(--text); font-size: 0.875rem;"><span style="background: ${statusColor}20; color: ${statusColor}; padding: 0.25rem 0.5rem; border-radius: 0.25rem; font-weight: 600; font-size: 0.75rem;">${r.成功件数 || 0}/${r.送信データ件数 || 0}</span></td>
          <td style="padding: 0.75rem; color: var(--text); font-size: 0.875rem;">${r.実行開始日時 ? new Date(r.実行開始日時).toLocaleString('ja-JP', { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' }) : "—"}</td>
          <td style="padding: 0.75rem; text-align: center; color: var(--text-muted); font-size: 0.875rem;">${r.処理時間秒 ? r.処理時間秒 + "s" : "—"}</td>
        </tr>
      `;
    }).join("");

    if (rows.length === 0) {
      tbody.innerHTML = `<tr style="background: rgba(0,0,0,0.1); height: 2rem;"><td colspan="6" style="padding: 1rem; text-align: center; color: var(--text-muted);">該当するデータがありません</td></tr>`;
    }
  }

  // KPI 更新関数
  function updateKPI(rows) {
    const total = rows.length;
    const success = rows.filter(r => r.処理ステータス === "成功").length;
    const error = rows.filter(r => r.処理ステータス === "失敗").length;
    kpiTotal.textContent = total;
    kpiSuccess.textContent = success;
    kpiError.textContent = error;
  }

  // 2. 初期データ読み込み
  window.aivicApi.list(tableIndex).then(rows => {
    allRows = rows || [];
    renderRows(allRows);
    updateKPI(allRows);
  });

  // 3. 行クリックでエラー詳細表示
  container.addEventListener("click", e => {
    const row = e.target.closest("tr[data-id]");
    if (row) {
      selectedRowId = row.dataset.id;
      const record = allRows.find(r => r.連携履歴ID === selectedRowId);
      if (record) {
        errorDetailContent.innerHTML = `
          <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 0.75rem;">
            <div><strong>連携ID:</strong> ${(record.連携履歴ID || "").substring(0, 12)}</div>
            <div><strong>連携種別:</strong> ${record.連携種別 || "—"}</div>
            <div><strong>ステータス:</strong> ${record.処理ステータス || "—"}</div>
            <div><strong>送信件数:</strong> ${record.送信データ件数 || 0}</div>
            <div><strong>成功件数:</strong> ${record.成功件数 || 0}</div>
            <div><strong>失敗件数:</strong> ${record.失敗件数 || 0}</div>
            <div><strong>実行開始:</strong> ${record.実行開始日時 ? new Date(record.実行開始日時).toLocaleString('ja-JP') : "—"}</div>
            <div><strong>実行終了:</strong> ${record.実行終了日時 ? new Date(record.実行終了日時).toLocaleString('ja-JP') : "—"}</div>
            <div><strong>処理時間:</strong> ${record.処理時間秒 ? record.処理時間秒 + "秒" : "—"}</div>
            <div><strong>実行トリガー:</strong> ${record.実行トリガー || "—"}</div>
          </div>
        `;
        errorMessageBox.textContent = record.エラー詳細 || "エラーなし";
        errorDetailPanel.style.display = "flex";

        // 再処理可能フラグ
        const retryBtn = container.querySelector("#btn-retry");
        if (record.処理ステータス === "失敗" && record.リトライ回数 < 3) {
          retryBtn.style.display = "block";
        } else {
          retryBtn.style.display = "none";
        }
      }
    }
  });

  // 詳細パネル閉じるボタン
  container.querySelector("#btn-close-detail").addEventListener("click", () => {
    errorDetailPanel.style.display = "none";
    selectedRowId = null;
  });

  // 4. 検索ボタン
  container.querySelector("#btn-search").addEventListener("click", () => {
    const date = container.querySelector("#filter-date").value;
    const status = container.querySelector("#filter-status").value;
    const errorType = container.querySelector("#filter-error-type").value;

    let filtered = allRows;
    if (date) {
      filtered = filtered.filter(r => {
        const rDate = r.実行開始日時 ? new Date(r.実行開始日時).toISOString().split('T')[0] : "";
        return rDate === date;
      });
    }
    if (status) {
      filtered = filtered.filter(r => r.処理ステータス === status);
    }
    if (errorType) {
      filtered = filtered.filter(r => {
        if (errorType === "警告") return r.失敗件数 > 0 && r.処理ステータス !== "失敗";
        return (r.エラー詳細 || "").includes(errorType);
      });
    }
    renderRows(filtered);
    updateKPI(filtered);
  });

  // 5. 受注ID検索
  container.querySelector("#btn-search-order").addEventListener("click", () => {
    const orderId = container.querySelector("#search-order-id").value.trim();
    if (!orderId) {
      renderRows(allRows);
      updateKPI(allRows);
      return;
    }
    const filtered = allRows.filter(r => 
      (r.連携履歴ID || "").includes(orderId) || 
      (r.備考 || "").includes(orderId)
    );
    renderRows(filtered);
    updateKPI(filtered);
  });

  // 6. 責任者フィルター
  container.querySelector("#btn-filter-owner").addEventListener("click", () => {
    const owner = container.querySelector("#filter-owner").value;
    if (!owner) {
      renderRows(allRows);
      updateKPI(allRows);
      return;
    }
    const filtered = allRows.filter(r => (r.備考 || "").includes(owner));
    renderRows(filtered);
    updateKPI(filtered);
  });

  // 7. 更新ボタン
  container.querySelector("[data-testid='refresh-button']").addEventListener("click", () => {
    window.aivicApi.list(tableIndex).then(rows => {
      allRows = rows || [];
      renderRows(allRows);
      updateKPI(allRows);
    });
  });

  // 8. CSV エクスポート
  container.querySelector("#btn-export").addEventListener("click", () => {
    const headers = ["連携ID", "連携種別", "連携方向", "ステータス", "送信件数", "成功件数", "失敗件数", "実行開始", "実行終了", "処理時間(秒)", "エラー詳細"];
    const rows = allRows.map(r => [
      r.連携履歴ID || "",
      r.連携種別 || "",
      r.連携方向 || "",
      r.処理ステータス || "",
      r.送信データ件数 || "",
      r.成功件数 || "",
      r.失敗件数 || "",
      r.実行開始日時 ? new Date(r.実行開始日時).toLocaleString('ja-JP') : "",
      r.実行終了日時 ? new Date(r.実行終了日時).toLocaleString('ja-JP') : "",
      r.処理時間秒 || "",
      (r.エラー詳細 || "").replace(/"/g, '""')
    ]);
    const csv = "\uFEFF" + [headers, ...rows].map(row => 
      row.map(cell => typeof cell === 'string' && cell.includes(',') ? `"${cell}"` : cell).join(',')
    ).join('\n');
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `連携結果_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // 9. 再処理ボタン
  container.querySelector("#btn-retry").addEventListener("click", async () => {
    if (!selectedRowId) return;
    if (!confirm("この連携を再処理しますか？")) return;
    const record = allRows.find(r => r.連携履歴ID === selectedRowId);
    if (record) {
      const updated = await window.aivicApi.update(tableIndex, selectedRowId, {
        リトライ回数: (record.リトライ回数 || 0) + 1,
        リトライ予定日時: new Date().toISOString()
      });
      if (updated) {
        alert("再処理をスケジュールしました");
        window.aivicApi.list(tableIndex).then(rows => {
          allRows = rows || [];
          renderRows(allRows);
          updateKPI(allRows);
        });
      }
    }
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックス（バリデーション結果: 0, 受注データ: 1, エラー分類: 2, 責任者: 3, 通知履歴: 4）
  const VALIDATION_RESULT_IDX = 0;
  const ORDER_IDX = 1;
  const ERROR_CLASS_IDX = 2;
  const RESPONSIBLE_IDX = 3;
  const NOTIFICATION_IDX = 4;

  // 現在選択中の失敗レコード
  let selectedFailure = null;

  // 1. 失敗一覧を再描画
  function renderFailures(rows) {
    const tbody = container.querySelector("#failure-tbody");
    if (!rows || rows.length === 0) {
      tbody.innerHTML = `<tr style="background: rgba(0,0,0,0.15);"><td colspan="4" style="padding: 12px; text-align: center; color: var(--text-muted);">バリデーション失敗がありません</td></tr>`;
      return;
    }
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id || ''}" style="cursor: pointer; border-bottom: 1px solid rgba(255,255,255,0.08); transition: background 0.2s;" onmouseover="this.style.background='rgba(255,255,255,0.05)'" onmouseout="this.style.background=''">
        <td style="padding: 6px 8px; color: var(--text);">${r.受注データID ? r.受注データID.substring(0, 8) : '-'}</td>
        <td style="padding: 6px 8px; color: var(--text);">${r.エラーコード || '-'}</td>
        <td style="padding: 6px 8px; color: var(--text-muted); font-size: 11px; max-width: 200px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">${r.エラーメッセージ || '-'}</td>
        <td style="padding: 6px 8px; color: var(--text-muted); font-size: 11px;">${r.実行日時 ? new Date(r.実行日時).toLocaleString('ja-JP') : '-'}</td>
      </tr>
    `).join("");
  }

  // 2. 初期データ読み込み
  window.aivicApi.list(VALIDATION_RESULT_IDX).then(rows => {
    renderFailures(rows || []);
  });

  // 3. フィルター適用
  container.querySelector("[data-testid='apply-filter']").addEventListener("click", async () => {
    const categoryFilter = container.querySelector("[data-testid='error-category-filter']").value;
    const statusFilter = container.querySelector("[data-testid='status-filter']").value;

    const rows = await window.aivicApi.list(VALIDATION_RESULT_IDX);
    const filtered = (rows || []).filter(r => {
      const matchCategory = !categoryFilter || (r.エラーコード && r.エラーコード.includes(categoryFilter));
      const matchStatus = !statusFilter || r.ステータス === statusFilter;
      return matchCategory && matchStatus;
    });
    renderFailures(filtered);
  });

  // 4. 更新ボタン
  container.querySelector("[data-testid='refresh-failures']").addEventListener("click", async () => {
    const rows = await window.aivicApi.list(VALIDATION_RESULT_IDX);
    renderFailures(rows || []);
  });

  // 5. 失敗行クリック → 詳細表示・プレビュー更新
  container.querySelector("#failure-tbody").addEventListener("click", async (e) => {
    const tr = e.target.closest("tr");
    if (!tr) return;

    selectedFailure = {
      id: tr.dataset.id,
      受注データID: tr.cells[0].textContent,
      エラーコード: tr.cells[1].textContent,
      エラーメッセージ: tr.cells[2].textContent,
      実行日時: tr.cells[3].textContent
    };

    // 行をハイライト
    container.querySelectorAll("#failure-tbody tr").forEach(row => row.style.background = "");
    tr.style.background = "rgba(255,165,0,0.15)";

    // プレビュー更新
    updatePreview();
  });

  // 6. プレビュー更新
  function updatePreview() {
    if (!selectedFailure) {
      container.querySelector("#preview-content").textContent = "失敗レコードを選択してください";
      container.querySelector("#preview-recipients").textContent = "選択してください";
      return;
    }

    const template = container.querySelector("[data-testid='template-select']").value;
    const channels = Array.from(container.querySelectorAll("input[type='checkbox']:checked")).map(cb => cb.value).join(", ");
    const responsible = container.querySelector("[data-testid='responsible-select']").value;

    let content = `【バリデーション失敗通知】\n\n`;
    content += `受注ID: ${selectedFailure.受注データID}\n`;
    content += `エラー分類: ${selectedFailure.エラーコード}\n`;
    content += `詳細: ${selectedFailure.エラーメッセージ}\n`;
    content += `発生日時: ${selectedFailure.実行日時}\n\n`;
    content += `テンプレート: ${template || 'なし'}\n`;
    content += `通知チャネル: ${channels || 'なし'}\n`;
    content += `対象者: ${responsible || 'なし'}\n`;

    container.querySelector("#preview-content").textContent = content;
    container.querySelector("#preview-recipients").textContent = responsible ? `${responsible}へ通知予定` : "選択してください";
  }

  // 7. 通知設定変更時にプレビュー更新
  container.querySelector("[data-testid='responsible-select']").addEventListener("change", updatePreview);
  container.querySelector("[data-testid='template-select']").addEventListener("change", updatePreview);
  container.querySelectorAll("input[type='checkbox']").forEach(cb => {
    cb.addEventListener("change", updatePreview);
  });

  // 8. タブ切り替え
  container.querySelectorAll(".tab-btn").forEach(btn => {
    btn.addEventListener("click", () => {
      const tabId = btn.dataset.tab;
      container.querySelectorAll(".tab-btn").forEach(b => {
        b.style.color = "var(--text-muted)";
        b.style.borderBottomColor = "transparent";
      });
      btn.style.color = "var(--text)";
      btn.style.borderBottomColor = "var(--primary)";

      container.querySelectorAll(".tab-content").forEach(tab => tab.style.display = "none");
      container.querySelector(`#${tabId}`).style.display = "flex";
    });
  });

  // 9. 即時通知ボタン
  container.querySelector("[data-testid='send-now-button']").addEventListener("click", async () => {
    if (!selectedFailure) {
      alert("失敗レコードを選択してください");
      return;
    }

    const responsible = container.querySelector("[data-testid='responsible-select']").value;
    const channels = Array.from(container.querySelectorAll("input[type='checkbox']:checked")).map(cb => cb.value);

    if (!responsible || channels.length === 0) {
      alert("通知対象者とチャネルを選択してください");
      return;
    }

    const notificationData = {
      バリデーション結果ID: selectedFailure.id,
      受注データID: selectedFailure.受注データID,
      責任者ID: responsible,
      通知タイプ: "エラー通知",
      通知ステータス: "未送信",
      通知内容: container.querySelector("#preview-content").textContent,
      再送回数: 0
    };

    const saved = await window.aivicApi.save(NOTIFICATION_IDX, notificationData);
    if (saved) {
      alert("通知を送信しました");
    }
  });

  // 10. ルール保存ボタン
  container.querySelector("[data-testid='save-rule-button']").addEventListener("click", async () => {
    const responsible = container.querySelector("[data-testid='responsible-select']").value;
    const channels = Array.from(container.querySelectorAll("input[type='checkbox']:checked")).map(cb => cb.value);
    const schedule = container.querySelector("[data-testid='schedule-select']").value;

    if (!responsible || channels.length === 0) {
      alert("通知対象者とチャネルを選択してください");
      return;
    }

    alert(`ルールを保存しました\n対象者: ${responsible}\nチャネル: ${channels.join(", ")}\nスケジュール: ${schedule || "なし"}`);
  });

  // 11. モーダル閉じる
  container.querySelector("#close-modal").addEventListener("click", () => {
    container.querySelector("#order-detail-modal").style.display = "none";
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックスの特定
  const batchTableIdx = tables.findIndex(t => t.tableName === '基幹システム連携履歴') ?? 0;
  const reflectionTableIdx = tables.findIndex(t => t.tableName === '連携反映状況') ?? 1;
  const errorLogTableIdx = tables.findIndex(t => t.tableName === 'エラーログ') ?? 2;
  const varianceTableIdx = tables.findIndex(t => t.tableName === '月次差異検証') ?? 3;
  const approvedTableIdx = tables.findIndex(t => t.tableName === '承認済み受注') ?? 4;

  const batchTimeline = container.querySelector('#batch-timeline');
  const statusSummary = container.querySelector('#status-summary');
  const errorClassification = container.querySelector('#error-classification');
  const monthlyVariance = container.querySelector('#monthly-variance');
  const approvedOrders = container.querySelector('#approved-orders');
  const errorDetailModal = container.querySelector('#error-detail-modal');
  const errorLogTbody = container.querySelector('#error-log-tbody');
  const closeErrorModal = container.querySelector('#close-error-modal');
  const btnCloseModal = container.querySelector('#btn-close-modal');
  const btnExportErrors = container.querySelector('#btn-export-errors');

  let selectedBatchId = null;
  let allErrorLogs = [];
  let allReflectionData = [];

  // 1. 連携バッチ一覧を描画（タイムライン形式）
  function renderBatchTimeline(batches) {
    batchTimeline.innerHTML = batches
      .sort((a, b) => new Date(b.実行開始日時) - new Date(a.実行開始日時))
      .slice(0, 20)
      .map(batch => {
        const statusColor = batch.処理ステータス === '成功' ? '#4ade80' : batch.処理ステータス === '部分成功' ? '#f97316' : '#ef4444';
        const statusLabel = batch.処理ステータス === '成功' ? '✓ 成功' : batch.処理ステータス === '部分成功' ? '⚠ 部分成功' : '✗ 失敗';
        const startTime = new Date(batch.実行開始日時).toLocaleString('ja-JP', { month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' });
        return `
          <div class="batch-item" data-batch-id="${batch.連携履歴ID}" style="padding: 10px; border-left: 3px solid ${statusColor}; background: rgba(255,255,255,0.02); cursor: pointer; border-radius: 4px; transition: background 0.2s;" data-testid="batch-item-${batch.連携履歴ID}">
            <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 4px;">
              <div style="font-size: 11px; font-weight: 600; color: var(--text);">${batch.連携種別}</div>
              <div style="font-size: 10px; color: ${statusColor}; font-weight: 600;">${statusLabel}</div>
            </div>
            <div style="font-size: 10px; color: var(--text-muted); margin-bottom: 4px;">${startTime}</div>
            <div style="font-size: 10px; color: var(--text); display: grid; grid-template-columns: 1fr 1fr; gap: 4px;">
              <div>受信: <span style="font-weight: 600;">${batch.送信データ件数}</span></div>
              <div>成功: <span style="font-weight: 600; color: #4ade80;">${batch.成功件数}</span></div>
            </div>
          </div>
        `;
      })
      .join('');

    // バッチアイテムのクリックイベント
    container.querySelectorAll('.batch-item').forEach(item => {
      item.addEventListener('click', () => {
        selectedBatchId = item.dataset.batchId;
        container.querySelectorAll('.batch-item').forEach(i => i.style.background = 'rgba(255,255,255,0.02)');
        item.style.background = 'rgba(255,215,0,0.1)';
        loadBatchDetails(selectedBatchId);
      });
    });
  }

  // 2. バッチ詳細を読み込んで表示
  function loadBatchDetails(batchId) {
    const batch = (tables[batchTableIdx]?.records || []).find(b => b.連携履歴ID === batchId);
    if (!batch) return;

    // ステータスサマリー
    statusSummary.style.display = 'block';
    container.querySelector('#summary-received').textContent = batch.送信データ件数 || 0;
    container.querySelector('#summary-success').textContent = batch.成功件数 || 0;
    container.querySelector('#summary-failed').textContent = batch.失敗件数 || 0;
    container.querySelector('#summary-skipped').textContent = (batch.送信データ件数 - batch.成功件数 - batch.失敗件数) || 0;
    container.querySelector('#summary-start').textContent = new Date(batch.実行開始日時).toLocaleString('ja-JP');
    container.querySelector('#summary-end').textContent = batch.実行終了日時 ? new Date(batch.実行終了日時).toLocaleString('ja-JP') : '-';

    // 連携反映状況からエラー分類集計
    allReflectionData = (tables[reflectionTableIdx]?.records || []).filter(r => r.基幹システム連携履歴ID === batchId);
    renderErrorClassification(allReflectionData);

    // 月次差異検証
    const variance = (tables[varianceTableIdx]?.records || []).find(v => v.基幹システム連携履歴ID === batchId);
    if (variance) {
      monthlyVariance.style.display = 'block';
      container.querySelector('#variance-month').textContent = variance.検証年月 || '-';
      container.querySelector('#variance-count').textContent = (tables[varianceTableIdx]?.records || []).filter(v => v.基幹システム連携履歴ID === batchId).length;
    }

    // 承認済み受注ステータス
    const approvedList = (tables[approvedTableIdx]?.records || []).filter(a => a.基幹システム連携履歴ID === batchId);
    if (approvedList.length > 0) {
      approvedOrders.style.display = 'block';
      container.querySelector('#approved-count').textContent = approvedList.length;
      container.querySelector('#linked-count').textContent = approvedList.filter(a => a.連携ステータス === '連携済み').length;
    }

    // エラーログ読み込み
    allErrorLogs = (tables[errorLogTableIdx]?.records || []).filter(e => e.バリデーション結果ID === batch.連携履歴ID);
  }

  // 3. エラー分類別集計を描画
  function renderErrorClassification(reflectionData) {
    const errorCounts = {};
    reflectionData.forEach(r => {
      const code = r.エラー分類マスタID || '不明';
      errorCounts[code] = (errorCounts[code] || 0) + 1;
    });

    const errorClassList = container.querySelector('#error-class-list');
    errorClassList.innerHTML = Object.entries(errorCounts)
      .map(([code, count]) => `
        <div style="display: flex; justify-content: space-between; align-items: center; padding: 6px; background: rgba(255,255,255,0.02); border-radius: 3px;">
          <div style="font-size: 11px; color: var(--text);">${code}</div>
          <div style="font-size: 12px; font-weight: 600; color: #ef4444;">${count}</div>
        </div>
      `)
      .join('');

    errorClassification.style.display = 'block';
  }

  // 4. エラー詳細モーダルを開く
  function openErrorDetailModal() {
    errorDetailModal.style.display = 'flex';
    renderErrorLogTable(allErrorLogs);
  }

  // 5. エラーログテーブルを描画
  function renderErrorLogTable(logs) {
    const filterCode = container.querySelector('#filter-error-code').value.toLowerCase();
    const filterSeverity = container.querySelector('#filter-severity').value;
    const filterStatus = container.querySelector('#filter-status').value;

    const filtered = logs.filter(log => {
      const codeMatch = !filterCode || (log.エラーコード || '').toLowerCase().includes(filterCode);
      const severityMatch = !filterSeverity || log.重要度 === filterSeverity;
      const statusMatch = !filterStatus || log.ステータス === filterStatus;
      return codeMatch && severityMatch && statusMatch;
    });

    errorLogTbody.innerHTML = filtered
      .map(log => {
        const severityColor = log.重要度 === 'CRITICAL' ? '#ef4444' : log.重要度 === 'ERROR' ? '#f97316' : log.重要度 === 'WARNING' ? '#fbbf24' : '#9fb0d1';
        return `
          <tr style="border-bottom: 1px solid rgba(255,255,255,0.05);">
            <td style="padding: 8px; color: var(--text); font-family: monospace; font-size: 11px;">${log.エラーコード || '-'}</td>
            <td style="padding: 8px; color: var(--text); font-size: 11px; max-width: 300px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;" title="${log.エラーメッセージ || ''}">${log.エラーメッセージ || '-'}</td>
            <td style="padding: 8px; text-align: center; color: ${severityColor}; font-weight: 600; font-size: 11px;">${log.重要度 || '-'}</td>
            <td style="padding: 8px; text-align: center; color: var(--text); font-size: 11px;">${log.ステータス || '-'}</td>
            <td style="padding: 8px; color: var(--text-muted); font-size: 10px;">${log.作成日時 ? new Date(log.作成日時).toLocaleString('ja-JP', { month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' }) : '-'}</td>
          </tr>
        `;
      })
      .join('');
  }

  // 6. CSVエクスポート
  function exportErrorsToCSV() {
    const headers = ['エラーコード', 'メッセージ', '重要度', 'ステータス', '発生日時'];
    const rows = allErrorLogs.map(log => [
      log.エラーコード || '',
      log.エラーメッセージ || '',
      log.重要度 || '',
      log.ステータス || '',
      log.作成日時 ? new Date(log.作成日時).toLocaleString('ja-JP') : ''
    ]);

    const csv = '\uFEFF' + [headers, ...rows]
      .map(row => row.map(cell => `"${String(cell).replace(/"/g, '""')}"`).join(','))
      .join('\n');

    const blob = new Blob([csv], { type: 'text/csv; charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `error-log-${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 7. イベントリスナー登録
  closeErrorModal.addEventListener('click', () => {
    errorDetailModal.style.display = 'none';
  });

  btnCloseModal.addEventListener('click', () => {
    errorDetailModal.style.display = 'none';
  });

  btnExportErrors.addEventListener('click', exportErrorsToCSV);

  container.querySelector('#filter-error-code').addEventListener('input', () => renderErrorLogTable(allErrorLogs));
  container.querySelector('#filter-severity').addEventListener('change', () => renderErrorLogTable(allErrorLogs));
  container.querySelector('#filter-status').addEventListener('change', () => renderErrorLogTable(allErrorLogs));

  // 8. 初期データ読み込み
  window.aivicApi.list(batchTableIdx).then(batches => {
    renderBatchTimeline(batches);
    if (batches.length > 0) {
      selectedBatchId = batches[0].連携履歴ID;
      container.querySelector('.batch-item').style.background = 'rgba(255,215,0,0.1)';
      loadBatchDetails(selectedBatchId);
    }
  }).catch(() => {
    renderBatchTimeline(tables[batchTableIdx]?.records || []);
  });

  // エラー詳細を表示するボタン（ステータスサマリーの下に追加）
  const showErrorsBtn = document.createElement('button');
  showErrorsBtn.className = 'action-btn';
  showErrorsBtn.textContent = 'エラー詳細を表示';
  showErrorsBtn.style.cssText = 'padding: 6px 12px; font-size: 12px; margin-top: 8px; width: 100%;';
  showErrorsBtn.dataset.testid = 'show-error-details-button';
  showErrorsBtn.addEventListener('click', openErrorDetailModal);
  statusSummary.appendChild(showErrorsBtn);
}

function(container, apiUrl, tables) {
  const orderTbody = container.querySelector("#order-tbody");
  const pendingTbody = container.querySelector("#pending-tbody");
  const errorCountEl = container.querySelector("#error-count");
  const validatedCountEl = container.querySelector("#validated-count");
  const errorClassificationEl = container.querySelector("#error-classification");
  const syncTimelineEl = container.querySelector("#sync-timeline");
  const monthlyVarianceEl = container.querySelector("#monthly-variance");
  const approvalModal = container.querySelector("#approval-modal");
  const approvalOrderInfo = container.querySelector("#approval-order-info");
  const approvalComment = container.querySelector("#approval-comment");

  let currentOrders = [];
  let currentErrors = [];
  let currentPendingApprovals = [];
  let currentSyncHistory = [];
  let currentMonthlyVariance = [];
  let selectedApprovalOrderId = null;

  // 1. 受注データ再描画
  function renderOrders(orders) {
    currentOrders = orders;
    orderTbody.innerHTML = orders.map(o => `
      <tr data-id="${o.id}" style="border-bottom: 1px solid rgba(255,255,255,0.08); cursor: pointer;" onclick="this.style.background='rgba(255,255,255,0.08)'">
        <td style="padding: 6px; color: var(--text);">${o.受注番号 || ""}</td>
        <td style="padding: 6px; color: var(--text);">${(o.受注金額 || 0).toLocaleString()}円</td>
        <td style="padding: 6px; color: var(--text);"><span style="background: ${o.ステータス === "完了" ? "rgba(100,200,100,0.3)" : o.ステータス === "キャンセル" ? "rgba(255,100,100,0.3)" : "rgba(100,150,200,0.3)"}; padding: 2px 6px; border-radius: 2px; font-size: 11px;">${o.ステータス || ""}</span></td>
      </tr>
    `).join("") || `<tr style="background: rgba(0,0,0,0.15);"><td colspan="3" style="padding: 8px; text-align: center; color: var(--text-muted);">データなし</td></tr>`;
  }

  // 2. 承認待ち受注再描画
  function renderPendingApprovals(orders) {
    currentPendingApprovals = orders;
    pendingTbody.innerHTML = orders.map(o => `
      <tr data-id="${o.id}" style="border-bottom: 1px solid rgba(255,255,255,0.08);">
        <td style="padding: 4px; color: var(--text);">${o.受注番号 || ""}</td>
        <td style="padding: 4px; text-align: right; color: var(--text);">${(o.受注金額 || 0).toLocaleString()}円</td>
        <td style="padding: 4px; text-align: center;">
          <button class="approve-order-btn" data-id="${o.id}" style="padding: 2px 6px; font-size: 10px; background: var(--primary); color: #fff; border: none; border-radius: 2px; cursor: pointer; margin-right: 2px;">承認</button>
          <button class="reject-order-btn" data-id="${o.id}" style="padding: 2px 6px; font-size: 10px; background: rgba(255,100,100,0.3); color: #ff6464; border: 1px solid #ff6464; border-radius: 2px; cursor: pointer;">却下</button>
        </td>
      </tr>
    `).join("") || `<tr style="background: rgba(0,0,0,0.15);"><td colspan="3" style="padding: 8px; text-align: center; color: var(--text-muted); font-size: 11px;">承認待ちなし</td></tr>`;
  }

  // 3. エラー集計再描画
  function renderErrorStats(errors) {
    currentErrors = errors;
    const errorCount = errors.filter(e => e.検証ステータス === "失敗").length;
    const validatedCount = errors.filter(e => e.検証ステータス === "成功").length;
    errorCountEl.textContent = errorCount;
    validatedCountEl.textContent = validatedCount;

    // エラー分類別集計
    const classification = {};
    errors.forEach(e => {
      const cat = e.エラー種別 || "その他";
      classification[cat] = (classification[cat] || 0) + 1;
    });

    errorClassificationEl.innerHTML = Object.entries(classification).map(([cat, count]) => `
      <div style="padding: 6px; background: rgba(0,0,0,0.2); margin-bottom: 4px; border-radius: 2px; display: flex; justify-content: space-between;">
        <span style="color: var(--text);">${cat}</span>
        <span style="color: #ff6464; font-weight: 600;">${count}</span>
      </div>
    `).join("") || `<div style="color: var(--text-muted); text-align: center; padding: 12px 0;">エラーなし</div>`;
  }

  // 4. 連携履歴タイムライン再描画
  function renderSyncHistory(history) {
    currentSyncHistory = history;
    syncTimelineEl.innerHTML = history.slice(0, 8).map(h => `
      <div style="padding: 8px; border-left: 2px solid ${h.処理ステータス === "成功" ? "#64c864" : h.処理ステータス === "失敗" ? "#ff6464" : "#ffa500"}; margin-bottom: 6px; background: rgba(0,0,0,0.2); border-radius: 2px;">
        <div style="font-size: 11px; color: var(--text); font-weight: 600;">${h.連携種別 || "連携"}</div>
        <div style="font-size: 10px; color: var(--text-muted);">${new Date(h.実行開始日時).toLocaleString()}</div>
        <div style="font-size: 10px; color: ${h.処理ステータス === "成功" ? "#64c864" : "#ff6464"};">${h.処理ステータス || ""} (${h.成功件数 || 0}/${h.送信データ件数 || 0})</div>
      </div>
    `).join("") || `<div style="color: var(--text-muted); text-align: center; padding: 20px 0;">履歴なし</div>`;
  }

  // 5. 月次差異検証再描画
  function renderMonthlyVariance(variance) {
    currentMonthlyVariance = variance;
    monthlyVarianceEl.innerHTML = variance.slice(0, 6).map(v => `
      <div style="padding: 8px; background: rgba(0,0,0,0.2); margin-bottom: 4px; border-radius: 2px; border-left: 2px solid ${v.検証ステータス === "解決済" ? "#64c864" : v.検証ステータス === "確認中" ? "#ffa500" : "#ff6464"};">
        <div style="font-size: 11px; color: var(--text); font-weight: 600;">${v.差異タイプ || "差異"}</div>
        <div style="font-size: 10px; color: var(--text-muted);">${v.検証年月 || ""}</div>
        <div style="font-size: 10px; color: var(--text);">差異額: ${(v.差異金額 || 0).toLocaleString()}円</div>
      </div>
    `).join("") || `<div style="color: var(--text-muted); text-align: center; padding: 20px 0;">差異なし</div>`;
  }

  // 6. 初期データ読み込み
  async function loadAllData() {
    try {
      const orders = await window.aivicApi.list(0);
      const errors = await window.aivicApi.list(4);
      const pendingApprovals = await window.aivicApi.list(13);
      const syncHistory = await window.aivicApi.list(10);
      const monthlyVariance = await window.aivicApi.list(9);

      renderOrders(orders || []);
      renderErrorStats(errors || []);
      renderPendingApprovals(pendingApprovals || []);
      renderSyncHistory(syncHistory || []);
      renderMonthlyVariance(monthlyVariance || []);
    } catch (e) {
      console.error("Data load error:", e);
    }
  }

  // 7. 検索ボタン
  container.querySelector("[data-testid='search-button']").addEventListener("click", async () => {
    const orderNum = container.querySelector("[data-testid='order-number-search']").value.trim();
    const status = container.querySelector("[data-testid='status-filter']").value;

    let filtered = currentOrders;
    if (orderNum) filtered = filtered.filter(o => (o.受注番号 || "").includes(orderNum));
    if (status) filtered = filtered.filter(o => o.ステータス === status);

    renderOrders(filtered);
  });

  // 8. バリデーション実行
  container.querySelector("[data-testid='validate-button']").addEventListener("click", async () => {
    try {
      const errors = await window.aivicApi.list(4);
      renderErrorStats(errors || []);
      alert("バリデーション実行完了");
    } catch (e) {
      console.error("Validation error:", e);
    }
  });

  // 9. エラークリア
  container.querySelector("[data-testid='clear-errors-button']").addEventListener("click", () => {
    renderErrorStats([]);
  });

  // 10. 承認ボタンのイベントデリゲーション
  container.addEventListener("click", async e => {
    const approveBtn = e.target.closest(".approve-order-btn");
    if (approveBtn) {
      selectedApprovalOrderId = approveBtn.dataset.id;
      const order = currentPendingApprovals.find(o => o.id === selectedApprovalOrderId);
      if (order) {
        approvalOrderInfo.textContent = `受注番号: ${order.受注番号} | 金額: ${(order.受注金額 || 0).toLocaleString()}円`;
        approvalComment.value = "";
        approvalModal.removeAttribute("hidden");
      }
    }

    const rejectBtn = e.target.closest(".reject-order-btn");
    if (rejectBtn) {
      if (confirm("この受注を却下しますか？")) {
        await window.aivicApi.delete(13, rejectBtn.dataset.id);
        loadAllData();
      }
    }
  });

  // 11. 承認モーダルの承認ボタン
  container.querySelector("[data-testid='approve-button']").addEventListener("click", async () => {
    if (selectedApprovalOrderId) {
      try {
        await window.aivicApi.update(13, selectedApprovalOrderId, {
          承認ステータス: "承認済み",
          承認コメント: approvalComment.value
        });
        approvalModal.setAttribute("hidden", "");
        loadAllData();
      } catch (e) {
        console.error("Approval error:", e);
      }
    }
  });

  // 12. 承認モーダルの却下ボタン
  container.querySelector("[data-testid='reject-button']").addEventListener("click", async () => {
    if (selectedApprovalOrderId) {
      try {
        await window.aivicApi.update(13, selectedApprovalOrderId, {
          承認ステータス: "却下",
          承認コメント: approvalComment.value
        });
        approvalModal.setAttribute("hidden", "");
        loadAllData();
      } catch (e) {
        console.error("Rejection error:", e);
      }
    }
  });

  // 13. 連携実行ボタン
  container.querySelector("[data-testid='sync-button']").addEventListener("click", async () => {
    if (confirm("基幹システムへの連携を実行しますか？")) {
      try {
        const syncRecord = {
          連携種別: "受注同期",
          連携方向: "送信",
          処理ステータス: "実行中",
          送信データ件数: currentOrders.length,
          成功件数: 0,
          失敗件数: 0,
          実行開始日時: new Date().toISOString(),
          実行トリガー: "手動"
        };
        await window.aivicApi.save(10, syncRecord);
        loadAllData();
        alert("連携を実行しました");
      } catch (e) {
        console.error("Sync error:", e);
      }
    }
  });

  // 14. 履歴を見るボタン
  container.querySelector("[data-testid='history-button']").addEventListener("click", () => {
    window.showScreen("scr-1781408614677");
  });

  // 15. 初期データ読み込み実行
  loadAllData();
}
